package com.investinator.remediation;
import static com.investinator.domain.Json.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.investinator.domain.Json;
import com.investinator.domain.Contracts.*;
import com.investinator.persistence.*;
import com.investinator.workflows.WorkflowService;
import com.investinator.monitoring.MonitoringService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.context.bean.override.mockito.MockitoSpyBean;
import org.testcontainers.junit.jupiter.*;
import org.testcontainers.postgresql.PostgreSQLContainer;
import org.junit.jupiter.api.*;
import java.util.*;
import java.util.concurrent.*;
@SpringBootTest(properties={"REMEDIATION_PLAN_TOKEN=fixture-planner","REMEDIATION_APPROVE_TOKEN=fixture-approver","REMEDIATION_EXECUTE_TOKEN=fixture-executor","REMEDIATION_VERIFY_TOKEN=fixture-verifier"})
@AutoConfigureMockMvc @Testcontainers
class RemediationIntegrationTest {
    @Container static final PostgreSQLContainer postgres=new PostgreSQLContainer(org.testcontainers.utility.DockerImageName.parse("postgres:16-alpine@sha256:81e77a4833487b8132fe4b00bedd39dc3f74b8641e387f19312a48f7de218c2e").asCompatibleSubstituteFor("postgres"));
    @DynamicPropertySource static void properties(DynamicPropertyRegistry p){p.add("investinator.persistence.enabled",()->true);p.add("investinator.persistence.url",postgres::getJdbcUrl);p.add("investinator.persistence.username",postgres::getUsername);p.add("investinator.persistence.password",postgres::getPassword);}
    @Autowired RemediationPolicy policy;@Autowired Store db;@Autowired WorkflowService workflows;@Autowired MonitoringService monitor;@Autowired MockMvc mvc;@Autowired org.springframework.core.env.ConfigurableEnvironment environment;
    @MockitoSpyBean ReplayExecutor executor;
    String incident;
    @BeforeEach void init(){db.jdbc.execute("truncate remediation_postmortems,remediation_plans,remediation_outbox,replay_resources,remediation_effects,remediation_samples,monitor_incidents,monitor_events,monitor_offsets,monitor_streaks,monitor_controls,monitor_outbox,monitor_deliveries,replay_runs,incidents,approvals,telemetry,alerts,execution_records,audit_events,request_keys cascade");incident=db.write("demo",()->workflows.replay("demo","kafka_disk_pressure")).get("incident_id").toString();}
    RemediationPolicy.Proposal request(){return new RemediationPolicy.Proposal(incident,"REPLAY_DISK_RECOVER_V1","ReplayLab",Map.of("disk_percent",60.0),null);}
    Map<String,Object> plan(){return policy.propose("demo",request(),true);}
    String id(Map<String,Object> p){return p.get("plan_id").toString();}String hash(Map<String,Object> p){return p.get("plan_hash").toString();}
    void approve(Map<String,Object> p){policy.approve("demo",id(p),hash(p),"APPROVE");}
    void execute(Map<String,Object> p){policy.execute("demo",id(p),hash(p),"key-"+id(p));}
    @Test void approvalAndAckNeverResolveWithoutIndependentFreshPostState()throws Exception{
        var dry=policy.propose("demo",request(),false);assertEquals(true,dry.get("dry_run"));assertEquals(0,db.jdbc.queryForObject("select count(*) from remediation_plans",Integer.class));assertEquals(0,db.jdbc.queryForObject("select count(*) from replay_resources",Integer.class));
        var p=plan();assertThrows(Exception.class,()->execute(p));approve(p);execute(p);assertEquals("EXECUTED",policy.get("demo",id(p)).get("state"));assertEquals(Lifecycle.investigating,workflows.incident("demo",incident).status);assertEquals(false,policy.verify("demo",id(p),hash(p)).get("passed"));policy.sample("demo",id(p));assertEquals(true,policy.verify("demo",id(p),hash(p)).get("passed"));assertEquals(Lifecycle.resolved,workflows.incident("demo",incident).status);assertEquals(1,db.jdbc.queryForObject("select count(*) from remediation_postmortems",Integer.class));assertTrue(map(db.all(Table.REPLAY_RUNS,"demo").getFirst().get("payload")).containsKey("steps"));
        java.nio.file.Files.createDirectories(java.nio.file.Path.of("target/remediation"));java.nio.file.Files.writeString(java.nio.file.Path.of("target/remediation/verified.json"),encode(obj("source_mode","SIMULATED","plan",policy.get("demo",id(p)),"audit",db.all(Table.AUDIT_EVENTS,"demo"),"effect_count",db.jdbc.queryForObject("select count(*) from remediation_effects",Integer.class),"production_actions",0)));
    }
    @Test void repeatedParallelAndWrongTenantExecutionHaveOnlyOneEffect()throws Exception{
        var p=plan();approve(p);try(var pool=Executors.newFixedThreadPool(2)){var jobs=new ArrayList<Future<Boolean>>();for(int i=0;i<2;i++)jobs.add(pool.submit(()->{try{execute(p);return true;}catch(com.investinator.api.ApiFailure expected){return false;}}));assertEquals(1,jobs.stream().map(f->{try{return f.get();}catch(Exception e){throw new RuntimeException(e);}}).filter(Boolean::booleanValue).count());}assertEquals(1,db.jdbc.queryForObject("select count(*) from remediation_effects",Integer.class));assertEquals(1,db.jdbc.queryForObject("select version from replay_resources",Integer.class));assertThrows(Exception.class,()->execute(p));assertThrows(Exception.class,()->policy.approve("other",id(p),hash(p),"APPROVE"));assertThrows(Exception.class,()->policy.execute("other",id(p),hash(p),"other-key"));
    }
    @Test void tokensAndBodyRoleSpoofingCannotConferApproval()throws Exception{
        var p=plan();String url="/api/v1/remediation/plans/"+id(p)+"/approval";String body=encode(obj("plan_hash",hash(p),"decision","APPROVE","decided_by","root-admin"));mvc.perform(post(url).contentType("application/json").content(body)).andExpect(status().isForbidden()).andExpect(header().exists("X-Request-ID"));mvc.perform(post(url).header("Authorization","Bearer fixture-planner").contentType("application/json").content(body)).andExpect(status().isForbidden());mvc.perform(post(url).header("Authorization","Bearer fixture-approver").contentType("application/json").content(body)).andExpect(status().isOk());assertEquals("demo.recovery_approver",db.jdbc.queryForObject("select approved_by from remediation_plans",String.class));
        mvc.perform(post("/api/v1/remediation/plans/"+id(p)+"/execute").header("Authorization","Bearer fixture-approver").header("Idempotency-Key","forged").contentType("application/json").content(encode(obj("plan_hash",hash(p))))).andExpect(status().isForbidden());
    }
    @Test void expiredRevokedAndStaleResourcePreconditionsDenyExecution(){
        var p=plan();approve(p);db.jdbc.update("update remediation_plans set approval_expires_at=now()-interval '1 second'");assertThrows(Exception.class,()->execute(p));var revoked=plan();approve(revoked);policy.approve("demo",id(revoked),hash(revoked),"REVOKE");assertThrows(Exception.class,()->execute(revoked));var stale=plan();approve(stale);db.jdbc.update("update replay_resources set observed_at=now()-interval '121 seconds'");assertThrows(Exception.class,()->execute(stale));assertEquals(0,db.jdbc.queryForObject("select count(*) from remediation_effects",Integer.class));
    }
    @Test void changedParametersDefinitionOrReviewHashAreRejected(){
        var p=plan();approve(p);assertThrows(Exception.class,()->policy.execute("demo",id(p),"different-hash","changed"));db.jdbc.update("update remediation_plans set payload=jsonb_set(payload,'{parameters,disk_percent}','20'::jsonb)");assertThrows(Exception.class,()->execute(p));assertEquals(0,db.jdbc.queryForObject("select count(*) from remediation_effects",Integer.class));
        assertThrows(Exception.class,()->policy.propose("demo",new RemediationPolicy.Proposal(incident,"REPLAY_DISK_RECOVER_V1","ReplayLab",Map.of("disk_percent",60,"shell","restart kafka"),null),true));assertThrows(Exception.class,()->policy.propose("demo",new RemediationPolicy.Proposal(incident,"DELETE_TOPIC","ReplayLab",Map.of(),null),true));assertThrows(Exception.class,()->policy.propose("demo",new RemediationPolicy.Proposal(incident,"REPLAY_DISK_RECOVER_V1","production",Map.of("disk_percent",60),null),true));
    }
    @Test void staleSamplesAndCallerClaimedChecksCannotVerify()throws Exception{
        var p=plan();policy.sample("demo",id(p));approve(p);execute(p);assertEquals(false,policy.verify("demo",id(p),hash(p)).get("passed"));policy.sample("demo",id(p));db.jdbc.update("update remediation_samples set observed_at=now()-interval '61 seconds'");assertEquals(false,policy.verify("demo",id(p),hash(p)).get("passed"));mvc.perform(post("/api/v1/remediation/plans/"+id(p)+"/verify").header("Authorization","Bearer fixture-verifier").contentType("application/json").content(encode(obj("plan_hash",hash(p),"checks",obj("passed",true),"verified_by","fake-admin")))).andExpect(status().isOk()).andExpect(jsonPath("$.passed").value(false));assertEquals(Lifecycle.investigating,workflows.incident("demo",incident).status);
    }
    @Test void interruptedBeforeEffectIsManualAndNeverAutomaticallyRetried(){var p=plan();approve(p);policy.claim("demo",id(p),hash(p),"interrupted");db.jdbc.update("update remediation_plans set lease_expires_at=now()-interval '1 second'");var restarted=new RemediationPolicy(db,workflows,monitor,executor,environment);assertEquals("REQUIRES_MANUAL_INTERVENTION",restarted.recover("demo",id(p)).get("state"));assertThrows(Exception.class,()->execute(p));assertEquals(0,db.jdbc.queryForObject("select count(*) from remediation_effects",Integer.class));}
    @Test void interruptedAfterEffectRecoversReceiptButStillRequiresIndependentSample(){var p=plan();approve(p);String lease=policy.claim("demo",id(p),hash(p),"effect-before-ack");executor.execute("demo",id(p),lease,map(p.get("plan")),hash(p));db.jdbc.update("update remediation_plans set lease_expires_at=now()-interval '1 second'");assertEquals("EXECUTED",new RemediationPolicy(db,workflows,monitor,executor,environment).recover("demo",id(p)).get("state"));assertEquals(false,policy.verify("demo",id(p),hash(p)).get("passed"));policy.sample("demo",id(p));assertEquals(true,policy.verify("demo",id(p),hash(p)).get("passed"));}
    @Test void acknowledgementWithoutEffectIsNotSuccess(){var p=plan();approve(p);org.mockito.Mockito.doNothing().when(executor).execute(org.mockito.ArgumentMatchers.eq("demo"),org.mockito.ArgumentMatchers.eq(id(p)),org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.anyMap(),org.mockito.ArgumentMatchers.eq(hash(p)));execute(p);assertEquals("REQUIRES_MANUAL_INTERVENTION",policy.get("demo",id(p)).get("state"));assertThrows(Exception.class,()->policy.verify("demo",id(p),hash(p)));assertEquals(Lifecycle.investigating,workflows.incident("demo",incident).status);}
    @Test void partialSuccessRetainsReceiptAndRequiresExplicitRecovery(){var p=plan();approve(p);org.mockito.Mockito.doAnswer(inv->{inv.callRealMethod();throw new IllegalStateException("owned partial-success fixture");}).when(executor).execute(org.mockito.ArgumentMatchers.eq("demo"),org.mockito.ArgumentMatchers.eq(id(p)),org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.anyMap(),org.mockito.ArgumentMatchers.eq(hash(p)));execute(p);assertEquals("REQUIRES_MANUAL_INTERVENTION",policy.get("demo",id(p)).get("state"));assertEquals(1,db.jdbc.queryForObject("select count(*) from remediation_effects",Integer.class));assertEquals(Lifecycle.investigating,workflows.incident("demo",incident).status);db.jdbc.update("update remediation_plans set lease_expires_at=now()-interval '1 second'");assertEquals("EXECUTED",policy.recover("demo",id(p)).get("state"));}
    @Test void namedRollbackRequiresOwnApprovalAndIndependentRestorationVerification(){var p=plan();approve(p);execute(p);policy.sample("demo",id(p));policy.verify("demo",id(p),hash(p));var request=new RemediationPolicy.Proposal(incident,"REPLAY_DISK_RESTORE_V1","ReplayLab",Map.of(),id(p));int before=db.jdbc.queryForObject("select count(*) from remediation_plans",Integer.class);policy.propose("demo",request,false);assertEquals(before,db.jdbc.queryForObject("select count(*) from remediation_plans",Integer.class));var rollback=policy.propose("demo",request,true);assertThrows(Exception.class,()->execute(rollback));approve(rollback);execute(rollback);assertEquals(false,policy.verify("demo",id(rollback),hash(rollback)).get("passed"));policy.sample("demo",id(rollback));assertEquals(true,policy.verify("demo",id(rollback),hash(rollback)).get("passed"));assertEquals("ROLLED_BACK",policy.get("demo",id(p)).get("state"));assertEquals(97.8,db.jdbc.queryForObject("select disk_percent from replay_resources",Double.class));assertEquals(Lifecycle.closed_unresolved,workflows.incident("demo",incident).status);}
    @Test void legacyAliasesCannotBypassGovernedPlanAndReadOnlyEnterpriseModesDenyWrites(){var p=plan();assertThrows(Exception.class,()->workflows.approval("demo",incident,"ACT-DEMO",new ApprovalDecision("approve","forged","attempt")));assertThrows(Exception.class,()->workflows.execute("demo",incident,"ACT-DEMO"));assertThrows(Exception.class,()->workflows.verify("demo",incident));var noEnterprise=new RemediationPolicy(db,workflows,monitor,executor,new org.springframework.mock.env.MockEnvironment().withProperty("investinator.demo-mode","false"));assertThrows(Exception.class,()->noEnterprise.propose("demo",request(),true));environment.getPropertySources().addFirst(new org.springframework.core.env.MapPropertySource("read-only-test",Map.of("investinator.remediation.read-only",true)));try{assertThrows(Exception.class,()->policy.propose("demo",request(),true));}finally{environment.getPropertySources().remove("read-only-test");}assertThrows(IllegalArgumentException.class,()->new RemediationPolicy(db,workflows,monitor,executor,new org.springframework.mock.env.MockEnvironment().withProperty("REMEDIATION_PLAN_TOKEN","same").withProperty("REMEDIATION_APPROVE_TOKEN","same")));assertEquals("PROPOSED",policy.get("demo",id(p)).get("state"));}
    @Test void databaseFailureBeforeReceiptRollsBackReplayMutation(){var p=plan();approve(p);db.jdbc.execute("create function remediation_test_failure() returns trigger language plpgsql as $$ begin raise exception 'owned simulated database outage'; end $$");db.jdbc.execute("create trigger remediation_test_interruption before insert on remediation_effects for each row execute function remediation_test_failure()");try{execute(p);assertEquals("REQUIRES_MANUAL_INTERVENTION",policy.get("demo",id(p)).get("state"));assertEquals(0,db.jdbc.queryForObject("select version from replay_resources",Integer.class));assertEquals(0,db.jdbc.queryForObject("select count(*) from remediation_effects",Integer.class));}finally{db.jdbc.execute("drop trigger remediation_test_interruption on remediation_effects");db.jdbc.execute("drop function remediation_test_failure()");}}
    @Test void monitoredDiskIncidentCanBindOnlyAnExplicitReplaySandboxAndFollowLifecycle(){
        var enabled=new org.springframework.mock.env.MockEnvironment().withProperty("investinator.monitor.enabled","true");var worker=new MonitoringService(db,workflows,graphs,rules,enabled,chat);worker.control("demo",false);String graph="governed-"+java.util.UUID.randomUUID();var time=java.time.Instant.now().minusSeconds(30);var node=new com.investinator.correlation.DependencyGraph.Node("broker",com.investinator.correlation.DependencyGraph.NodeType.BROKER,"SIMULATED broker");graphs.registerSimulation("demo",new com.investinator.correlation.DependencyGraph(graph,1,"SIMULATED","KRAFT","Kafka 4.3",List.of(node),List.of()),List.of());for(int i=0;i<2;i++)worker.accept("demo",new com.investinator.monitoring.MonitoringContracts.SignalReceived("governed-disk-"+i,"demo","demo","fixture-cluster",graph,1,"broker","disk",time.plusSeconds(i).toString(),"SIMULATED",Map.of("disk_percent",97.8),Set.of("disk_percent"),"SIMULATED",null));worker.tick("demo");String monitored=db.jdbc.queryForObject("select id from monitor_incidents",String.class);worker.transition("demo",monitored,com.investinator.monitoring.MonitoringContracts.Lifecycle.TRIAGED,false);worker.transition("demo",monitored,com.investinator.monitoring.MonitoringContracts.Lifecycle.INVESTIGATING,false);var p=policy.propose("demo",new RemediationPolicy.Proposal(monitored,"REPLAY_DISK_RECOVER_V1","ReplayLab",Map.of("disk_percent",60),null),true);assertEquals("AWAITING_APPROVAL",worker.incident("demo",monitored).get("lifecycle"));approve(p);execute(p);assertEquals("VERIFYING",worker.incident("demo",monitored).get("lifecycle"));assertEquals(Lifecycle.investigating,workflows.incident("demo",monitored).status);policy.sample("demo",id(p));policy.verify("demo",id(p),hash(p));assertEquals("RESOLVED",worker.incident("demo",monitored).get("lifecycle"));assertEquals("PENDING_KNOWLEDGE_REVIEW",map(policy.postmortem("demo",id(p))).get("review_state"));
    }
    @Autowired com.investinator.correlation.CorrelationService graphs;
    @Autowired com.investinator.monitoring.DetectionRules rules;
    @Autowired com.investinator.chat.ChatService chat;

}
